// TH14 v1.00b Stage 4 mid-stage wave MainSub03 (st04.ecl.txt:1129-1139)
// dependency closure: ECir01 (158-191) + ECir01_at (193-274)
// 4x ECir01, alternating mirror (M/normal/M/normal) at y=64/48/32/16, births 0/110/210/290.

const TIME_LIMIT: int = 1924;      // 120 opening buffer + 1800 schedule/exit estimate + 4
const OPENING_BUFFER: int = 120;
const ECIR01_HP: int = 150;        // source create line hp
const TH14_BALL: int = 416;        // source type 4 (TH14_BALL), see TH14 bullet aliases
const LASER_COLOR: int = 3;        // source etSprite(0, 20, 3) color field
const RING_COLOR: int = 8;         // source etSprite(1, 4, 8)

// ---- generic Hermite-Relmover -------------------------------------------------
// Native 426 moveBezierRel stores tangents (mode 8 Hermite), not control points:
// value(t) = h00*p0 + h10*m0 + h01*p1 + h11*m1 over frames=120.
// Target has no bound position-vector Hermite verb, so slots 0/1 are read per frame
// and written back with move_to(0).  Endpoint is written explicitly on the last frame.
sub card_bezier(x0: fx, y0: fx, x1: fx, y1: fx, t0x: fx, t0y: fx, t1x: fx, t1y: fx) {
    hermite_start(0, x0, x1, t0x, t1x, 120);
    hermite_start(1, y0, y1, t0y, t1y, 120);
    for k in 0..120 {
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
        wait(1);
    }
    move_to(0, x1, y1, EASE_LINEAR);
}

async sub card_bezier_async(x0: fx, y0: fx, x1: fx, y1: fx, t0x: fx, t0y: fx, t1x: fx, t1y: fx) {
    card_bezier(x0, y0, x1, y1, t0x, t0y, t1x, t1y);
}

// ---- native 700/702 Line laser -----------------------------------------------
// Source emitter 0: laserNew(0, 0, L, 0, 14), then etAngle(0, ANGLE_PLAYER + A, 0)
// and laserOn(0) per fan line.  As an emitter laser it has no timing script, so it
// is live from birth, grows to target length L and then travels at etSpeed.
// Hit segment for a Line with flags 0x2 clear is 0.1L..0.9L of its length; native
// width w=14 gives half-height 14/4, i.e. target full width 7.
// lz_start fixes the near end at 0.1L while lz_speed grows/slides it; the traveling
// rod is exactly 0.1L..0.9L, the growth phase is a constant-near-end approximation.
sub card_laser(a: angle, len: fx, spd: fx) {
    var h: int = laser(LASER_COLOR, $self_x, $self_y, a, len * 0.9fx, 7fx, 0, 400, 0);
    lz_start(h, len * 0.1fx);
    lz_speed(h, spd, len * 0.8fx);
}

// ---- ECir01_at (193-274) ------------------------------------------------------
// Rank values (E/N/H/L):
//   first wait   10/10/0/0
//   etSpeed      2.7/4.0/4.0/5.0
//   laserNew L   128/160/144/160
//   diffI C      1/1/2/5  (outer loop, C+1 volleys)
//   diffI D      3/5/5/7  (fan lines per volley, D+1)
//   diffF B      30/22.5/22.5/18 deg (A starts at +45 deg, A -= B per line)
//   rank>=1 ring: 8 bullets, mode 8 random angle/speed, alpha = aim - 15 deg,
//                 delta = 30 deg, speed 1..3, type 4 color 8.
//   per-volley wait 60/50/20/10 (also after the last volley, as in source)
async sub ecir01_at(rank: int) {
    var laser_len: fx = 160fx;
    var laser_speed: fx = 4fx;
    var fan_step: int = 5461;      // 30 deg in BAM
    var fan_count: int = 5;        // D
    var volleys: int = 1;          // C
    var gap: int = 50;
    var a: int = 8192;             // 45 deg in BAM (source 0.785398 rad)
    var left: int = 0;
    var lim: int = 0;
    var ang: angle = 0deg;
    var aim: angle = 0deg;
    var ra: int = 0;
    var rv: int = 0;
    var u: fx = 0fx;
    var su: fx = 0fx;
    var off: int = 0;
    if rank == 0 {
        laser_speed = 2.7fx;
        laser_len = 128fx;
        fan_step = 5461;
        fan_count = 3;
        volleys = 1;
        gap = 60;
    } else if rank == 2 {
        laser_len = 144fx;
        fan_step = 4096;           // 22.5 deg
        fan_count = 5;
        volleys = 2;
        gap = 20;
    } else if rank == 3 {
        laser_speed = 5fx;
        fan_step = 3277;           // 18 deg
        fan_count = 7;
        volleys = 5;
        gap = 10;
    }
    if rank < 2 {
        wait(10);
    }
    left = volleys;
    loop {
        a = 8192;
        lim = fan_count + 1;
        for j in 0..lim {
            // source: etAngle(0, ANGLE_PLAYER + A, 0); laserOn(0); A -= B
            ang = aim_player() + (a as angle);
            card_laser(ang, laser_len, laser_speed);
            a = a - fan_step;
        }
        if rank >= 1 {
            // source etAim(1, 8): one aim sample per wave, then per bullet
            // angle = aim - 15deg + U_signed*30deg, speed = 1 + U*2 (angle drawn first).
            aim = aim_player();
            for m in 0..8 {
                ra = rand(65536);
                su = (ra - 32768) as fx / 32768;
                off = (5461fx * su) as int;
                rv = rand(65536);
                u = (rv - 32768) as fx / 65536 + 0.5fx;
                _ = fire(TH14_BALL, RING_COLOR, $self_x, $self_y, 1fx + 2fx * u,
                         aim + (off as angle) - 2731bam, none, none);
            }
        }
        if left > 0 {
            left = left - 1;
            wait(gap);
        } else {
            return;
        }
    }
}

// ---- ECir01 (158-191) ---------------------------------------------------------
// dir is source A: +1 for enmCreate, -1 for enmCreateM (mirror bit set).
// Final position = ABS (spawn) + REL layer.  Source:
//   movePosRel(-192A, 0)                                  -> (-192A, y0)
//   moveBezierRel(120, 256A,-30, 160A,128, 0,0)          -> (160A, y0+128)
//   wait(120)  (ends exactly with the 120-frame bezier)  -> attack opens here
//   moveBezierRel(120, 0,0, -220A,192, -200A,-228)       -> (-220A, y0+192)
//   @ECir01_at() async
// card_bezier below is blocking, so it stands in for moveBezierRel + the wait(120).
// flagSet(15)=0xF: 0x2 body-collision gate during entry (cleared with the block);
// 0x4/0x8 offscreen-skip and 0x1 have no target public write, path stays on screen.
async sub ecir01(dir: fx, y0: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);             // source setHurtbox(24,24) -> radius 12
    set_hitbox(8fx);               // source setHitbox(16,16) -> radius 8
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(0, -192fx * dir, y0, EASE_LINEAR);
    card_bezier(-192fx * dir, y0, 160fx * dir, y0 + 128fx,
                256fx * dir, -30fx, 0fx, 0fx);
    set_enemy_flag(ENEMY_NO_BODY, 0);
    spawn card_bezier_async(160fx * dir, y0 + 128fx, -220fx * dir, y0 + 192fx,
                            0fx, 0fx, -200fx * dir, -228fx);
    spawn ecir01_at(global(GVAR_RANK));
    loop { wait(1000); }
}

// ---- MainSub03 (1129-1139) ----------------------------------------------------
// enmCreateM -> dir -1, enmCreate -> dir +1; waits 110/100/80 between creates.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 64fx, ECIR01_HP, 0, 0, 0, ecir01(-1fx, 64fx));
    wait(110);
    _ = spawn_enemy(0fx, 48fx, ECIR01_HP, 0, 0, 0, ecir01(1fx, 48fx));
    wait(100);
    _ = spawn_enemy(0fx, 32fx, ECIR01_HP, 0, 0, 0, ecir01(-1fx, 32fx));
    wait(80);
    _ = spawn_enemy(0fx, 16fx, ECIR01_HP, 0, 0, 0, ecir01(1fx, 16fx));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
